param([ValidateSet('safety-build','safety-test','build')][string]$Action='safety-build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-out-l1-shadow-20260914';$seed='D:\projects\AIMA-public-interleaved-projection-20260914';$source='b851e96c9db310fb935966761498fac186ef8ae9';$bundle='D:\projects\out-l1-shadow-b851e96.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'ce435d5ad44ce7f14120f63a75f9eb2531efca0228b1efaa546f5f9f8b85f748'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $source;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $source -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$safety=Join-Path $repo 'build\out-l1-shadow-safety';$provider=Join-Path $repo 'build\out-l1-shadow-provider'
$out=Join-Path $repo ('build\out-l1-shadow-'+$Action+'-r1');$specPath=Join-Path $repo ('build\out-l1-shadow-'+$Action+'-r1.json')
foreach($p in @($out,$specPath)){if(Test-Path $p){throw 'Evidence exists'}}
$null=New-Item -ItemType Directory -Path (Join-Path $repo 'build') -Force
$sourceFiles=@('native\providers\whole_provider.cpp','native\providers\q8192_matrix_producer_policy.h','native\providers\q8192_out_l1_policy.h','native\providers\q8192_out_l1_shadow_audit.h','tests\native\projection_safety_selftest.cpp','scripts\baiying_build_whole_provider.ps1')
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName.Substring($repo.Length+1)})
}
$sourceInputs=@();foreach($file in ($sourceFiles|Sort-Object -Unique)){$sourceInputs+=@{file=$file;sha256=(Get-FileHash (Join-Path $repo $file) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$source;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; native component validation';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;replay_lanes=4;purpose='Validate a read-only q8192 OUT L1 envelope audit. Complete2048x8192x4096 algorithm4 magnitude matrix is checked against77 independent exact dyadic sums,all16777216 outputs,source and magnitude immutability,row flags and typed redzones. Also run12 existing partial/mixed/extreme matrix cases. Audit coefficients1,4,8,16,32 do not drive inference; full512 GB10 product audit follows only after native validation.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$env:QRT_QWEN36_PROFILE_MATRIX_PRODUCER_WALL='0';$env:QRT_QWEN36_PREFILL_HIPBLASLT_PRODUCER='1';$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_ALGORITHM='4';$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_SCOPE='qkv';$env:QRT_QWEN36_Q8192_OUT_MATRIX_SHADOW_AUDIT='0';$env:QRT_QWEN36_Q8192_OUT_L1_SHADOW_AUDIT='0'
function Check-Run([string]$action){
 $path=Join-Path $repo ('build\out-l1-shadow-'+$action+'-r1\run-record.json');$r=[IO.File]::ReadAllText($path)|ConvertFrom-Json
 if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('Incomplete prerequisite '+$action)}
 return (Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()
}
if($Action -eq 'safety-test'){
 $spec.build_run_sha256=Check-Run 'safety-build'
 $metaPath=Join-Path $safety 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 $exe=Join-Path $safety 'qrt-projection-safety.exe';$artifact=@($meta.artifacts|Where-Object {$_.name -eq 'qrt-projection-safety.exe'})
 if($meta.repo_commit -ne $source -or $meta.dirty_tree -or $artifact.Count -ne 1 -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact[0].sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@('--out-l1-magnitude');$timeout=90
}else{
 if($Action -eq 'build'){$spec.safety_test_run_sha256=Check-Run 'safety-test';$build=$provider}else{$build=$safety}
 if(Test-Path $build){throw 'Build exists'}
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$build,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','240')
 if($Action -eq 'safety-build'){$spec.arguments+=@('-ProjectionSafetyTest')};$timeout=270
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native OUT L1 action failed'}
if($Action -eq 'safety-test'){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $summary=@($reports|Where-Object {$_.type -eq 'summary'});$full=@($reports|Where-Object {$_.type -eq 'out_l1_magnitude'});$other=@($reports|Where-Object {$_.kind -eq 'absolute_product_matrix_bound'})
 if($summary.Count -ne 1 -or $summary[0].status -ne 'pass' -or $summary[0].gpu_cases -ne 13 -or $full.Count -ne 1 -or $other.Count -ne 12){throw 'Incomplete native OUT magnitude tests'}
 if($full[0].cells -ne 16777216 -or $full[0].underestimates -ne 0 -or -not $full[0].redzones_pass -or -not $full[0].immutable_inputs){throw 'Full OUT magnitude mismatch'}
 foreach($x in $other){if($x.underestimates -ne 0 -or -not $x.redzones_pass -or -not $x.inputs_immutable){throw 'Existing matrix magnitude regression'}}
}
